\u724c\u4f4d\u7f6e\u53ca\u76f2\u6ce8\uff1b\u6c92\u6709\u7c4c\u78bc\u7684\u73a9\u5bb6\u4e0d\u53c3\u52a0\u3002\u7cfb\u7d71\u4e0d\u6703\u81ea\u52d5\u88dc\u5145\u7c4c\u78bc\u3002"),mus=c("\u56db\u540d\u73a9\u5bb6\u8207\u5c0d\u9762\u7684\u73a9\u5bb6\u642d\u6a94\uff0c\u5404\u62ff\u56db\u5f35\u724c\u3002\u6240\u6709\u4eba\u540c\u610f mus \u624d\u80fd\u63db\u724c\uff1b\u7d50\u675f\u63db\u724c\u5f8c\u958b\u59cb\u5404\u8f2a\u6bd4\u8f03\u3002\u63db\u724c\u6642\u53ef\u9078\u4efb\u610f\u624b\u724c\uff0c\u4e5f\u53ef\u4e00\u5f35\u4e0d\u63db\u3002","\u6bd4\u8f03\u5927\u724c\u3001\u5c0f\u724c\u3001\u5c0d\u5b50\u53ca juego\uff1b\u7121\u4eba\u6eff\u8db3 juego \u6642\u6bd4\u8f03 punto\u3002\u4f7f\u7528\u754c\u9762\u7684\u5408\u6cd5\u9078\u9805\uff0c\u5305\u62ec \u00f3rdago\u3002\u4e0b\u6ce8\u548c\u52a0\u8a3b\u5747\u6307\u5b9a\u8ced\u6ce8\u7e3d\u984d\u3002","\u4e0b\u4e00\u624b\u4fdd\u7559\u968a\u4f0d\u6bd4\u5206\u4e26\u8f2a\u63db mano\u3002\u76ee\u6a19\u5206\u7232\u914d\u7f6e\u768430\u621640\u5206\u3002\u6bd4\u8cfd\u7d50\u675f\u5f8c\uff0c\u65b0\u6bd4\u8cfd\u6703\u6e05\u96f6\u6bd4\u5206\uff0c\u4fdd\u7559\u73a9\u5bb6\u53ca\u898f\u5247\u3002"),blackjack=c("\u5118\u91cf\u6bd4\u838a\u5bb6\u5927\uff0c\u4f46\u4e0d\u80fd\u8d85\u904e21\u9ede\u3002A\u8a081\u621611\u9ede\uff1b\u539f\u59cb\u5169\u5f35\u724c\u768421\u9ede\u7232\u81ea\u7136\u4e8c\u5341\u4e00\u9ede\u3002\u838a\u5bb6\u6309\u914d\u7f6e\u898f\u5247\u884c\u52d5\u3002","\u8981\u724c\u589e\u52a0\u4e00\u5f35\uff1b\u505c\u724c\u4fdd\u7559\u9ede\u6578\u3002\u52a0\u500d\u8ffd\u52a0\u540c\u984d\u8ced\u6ce8\u3001\u62ff\u4e00\u5f35\u724c\u5f8c\u505c\u724c\uff1b\u5206\u724c\u628a\u76f8\u540c\u724c\u9762\u5206\u7232\u5169\u624b\u4e26\u8ffd\u52a0\u8ced\u6ce8\u3002\u7576\u524d\u624b\u724c\u6703\u7a81\u51fa\u986f\u793a\u3002","\u4e0b\u4e00\u8f2a\u4fdd\u7559\u9918\u984d\u4e26\u4f7f\u7528\u4f60\u78ba\u8a8d\u7684\u8ced\u6ce8\u3002\u6bcf\u8f2a\u91cd\u65b0\u6d17\u5b8c\u6574\u724c\u9774\uff0c\u4e0d\u9023\u7e8c\u4f7f\u7528\u4e0a\u4e00\u8f2a\u7684\u5269\u9918\u724c\uff1b\u9918\u984d\u5fc5\u9808\u8db3\u5920\u652f\u4ed8\u8ced\u6ce8\u3002"),scopa=c("\u6253\u51fa\u4e00\u5f35\u624b\u724c\u3002\u5982\u684c\u4e0a\u6709\u540c\u9ede\u724c\uff0c\u5fc5\u9808\u62ff\u53d6\uff1b\u5426\u5247\u62ff\u53d6\u9ede\u6578\u4e4b\u548c\u7b49\u65bc\u6240\u51fa\u724c\u7684\u7d44\u5408\u3002\u7121\u6cd5\u62ff\u53d6\u6642\u5c07\u6240\u51fa\u724c\u7559\u5728\u684c\u9762\u3002","\u9078\u4e2d\u624b\u724c\uff0c\u518d\u9078\u64c7\u7de8\u865f\u6355\u7372\u65b9\u6848\uff1b\u76f8\u61c9\u684c\u9762\u4f4d\u7f6e\u6703\u9ad8\u4eae\u3002\u6e05\u7a7a\u684c\u9762\u5f97\u4e00\u6b21 scopa\uff0c\u4f46\u4e00\u526f\u724c\u7684\u6700\u5f8c\u4e00\u6b21\u51fa\u724c\u4e0d\u8a08\u6e05\u6aaf\u5206\u3002","\u724c\u6578\u3001\u91d1\u5e63\u3001\u91d1\u5e63\u4e03\u3001primiera\u53ca\u6e05\u6aaf\u8a08\u5206\u3002\u5169\u4e09\u4eba\u5404\u81ea\u6bd4\u8cfd\uff0c\u56db\u4eba\u6309\u5c0d\u9762\u642d\u6a94\u3002\u4e0b\u4e00\u624b\u4fdd\u7559\u6bd4\u5206\uff0c\u9054\u5230\u76ee\u6a19\u5f8c\u7684\u65b0\u6bd4\u8cfd\u6e05\u96f6\u6bd4\u5206\u3002"),liar=c("\u9078\u724c\u80cc\u9762\u68c4\u51fa\uff0c\u4e26\u8072\u660e\u9ede\u6578\uff1b\u5141\u8a31\u8a50\u552c\u3002\u8072\u660e\u9ede\u6578\u4e00\u76f4\u4fdd\u6301\u5230\u6709\u4eba\u8cea\u7591\uff0c\u8acb\u9075\u5b88\u986f\u793a\u7684\u724c\u6578\u4e0a\u9650\u3002","\u56de\u61c9\u6642\u53ef\u8cea\u7591\u6700\u8fd1\u8072\u660e\uff0c\u6216\u904e\u724c\u653e\u68c4\u8cea\u7591\uff1b\u9019\u88cf\u904e\u724c\u4e0d\u80fd\u8df3\u904e\u51fa\u724c\u56de\u5408\u3002\u8a50\u552c\u88ab\u63ed\u7a7f\u6642\u8072\u660e\u8005\u6536\u8d70\u6574\u5806\uff0c\u5426\u5247\u8cea\u7591\u8005\u6536\u8d70\u3002\u53ea\u63ed\u793a\u6700\u8fd1\u8072\u660e\u7684\u4e00\u7d44\u724c\u3002","\u6253\u51fa\u6700\u5f8c\u7684\u724c\u5f8c\uff0c\u5fc5\u9808\u901a\u904e\u56de\u61c9\u968e\u6bb5\u624d\u80fd\u7372\u52dd\u3002\u4e0b\u4e00\u526f\u91cd\u65b0\u6d17\u914d\u7f6e\u7684\u724c\u7d44\u4e26\u8f2a\u63db\u9aee\u724c\u8005\uff0c\u4fdd\u7559\u539f\u73a9\u5bb6\u3002")))
